/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/** Open milestones one project may hold. Closed milestones do not count. */
export const MAX_OPEN_MILESTONES_PER_PROJECT: number = 10;

export type ProjectId = Branded<string, "ProjectId">;
export type MilestoneId = Branded<string, "MilestoneId">;
export type IssueId = Branded<string, "IssueId">;

export * from "./project";
export * from "./milestone";
export * from "./issue";

/**
 * Milestone state conflicts: a closed milestone used where an open one is
 * required, reopening an open milestone, the open-milestone cap, and a name
 * already used in the same project.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason) {
    super(`Milestone state conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}

/** Identity used for uniqueness: case-insensitive, surrounding spaces ignored. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

import type {
  IsoTimestamp,
  MilestoneId,
  ProjectId,
  TenantScoped,
  Timestamps,
} from "./common";

export interface Milestone extends Timestamps, TenantScoped {
  readonly id: MilestoneId;
  readonly projectId: ProjectId;
  readonly name: string;
  readonly targetDate: IsoTimestamp | null;
  readonly closedAt: IsoTimestamp | null;
}

export interface MilestoneProgress {
  readonly total: number;
  readonly open: number;
  readonly closed: number;
}

export interface MilestoneWithProgress {
  readonly milestone: Milestone;
  readonly progress: MilestoneProgress;
  readonly overdue: boolean;
}

export const projectIdSchema = brandedId<ProjectId>("projectId");
export const milestoneIdSchema = brandedId<MilestoneId>("milestoneId");
export const issueIdSchema = brandedId<IssueId>("issueId");

import { z } from "zod";
import {
  isoTimestampSchema,
  issueIdSchema,
  milestoneIdSchema,
  orgIdSchema,
  projectIdSchema,
} from "./common";

