import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const milestones = sqliteTable(
  "milestones",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    name: text("name").notNull(),
    /** Trimmed, lower-cased name. Unique per project, closed milestones included. */
    nameKey: text("name_key").notNull(),
    targetDate: text("target_date"),
    closedAt: text("closed_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("milestones_project_name_idx").on(table.projectId, table.nameKey),
    index("milestones_org_project_idx").on(table.orgId, table.projectId),
  ],
);

export type MilestoneRow = typeof milestones.$inferSelect;
export type NewMilestoneRow = typeof milestones.$inferInsert;

  index("issues_org_due_idx").on(table.orgId, table.dueAt),
  index("issues_milestone_idx").on(table.milestoneId),
],

