export async function setIssueMilestone(
  orgId: OrgId,
  issueId: IssueId,
  milestoneId: import("@/types/common").MilestoneId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

