/**
 * Milestone rows for one project: name identity, open-cap counts, and the
 * issue move that accompanies a close.
 */
import { and, count, eq, isNull, notInArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type { CreateMilestoneInput, UpdateMilestoneInput } from "@/schemas/milestone";
import type { IsoTimestamp, IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

export async function findMilestoneByNameKey(
  orgId: OrgId,
  projectId: ProjectId,
  nameKey: string,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        eq(milestones.nameKey, nameKey),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all();
  return rows.map(toMilestone);
}

export async function progressForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ReadonlyMap<string, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const byMilestone = new Map<string, { total: number; open: number; closed: number }>();
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const bucket = byMilestone.get(row.milestoneId) ?? { total: 0, open: 0, closed: 0 };
    const amount = row.value ?? 0;
    bucket.total += amount;
    if ((CLOSED_ISSUE_STATUSES as readonly string[]).includes(row.status)) {
      bucket.closed += amount;
    } else {
      bucket.open += amount;
    }
    byMilestone.set(row.milestoneId, bucket);
  }
  return byMilestone;
}

export async function insertMilestone(
  input: CreateMilestoneInput,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      nameKey: milestoneNameKey(input.name),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(input.name === undefined
        ? {}
        : { name: input.name, nameKey: milestoneNameKey(input.name) }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, input.orgId),
        eq(milestones.id, input.milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Moves every open live issue off `milestoneId` and stamps the milestone
 * closed, in one transaction. Closed and archived issues stay put.
 */
export async function closeMilestoneMovingIssues(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  return db.transaction((tx) => {
    const moved = tx
      .update(issues)
      .set({ milestoneId: moveTo, updatedAt: stamp })
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          isNull(issues.archivedAt),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      )
      .returning({ id: issues.id })
      .all();

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${milestoneId} not found`);

    return {
      milestone: toMilestone(row),
      movedIssueIds: moved.map((item) => item.id as IssueId),
    };
  });
}

/**
 * Project milestones: naming, the open-milestone cap, close-and-move, and progress.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneProgress, MilestoneWithProgress } from "@/types/milestone";

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

function isOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): boolean {
  if (milestone.closedAt !== null) return false;
  if (milestone.targetDate === null) return false;
  if (progress.open === 0) return false;
  return new Date(milestone.targetDate).getTime() < now.getTime();
}

function compareMilestones(a: Milestone, b: Milestone): number {
  const aClosed = a.closedAt === null ? 0 : 1;
  const bClosed = b.closedAt === null ? 0 : 1;
  if (aClosed !== bClosed) return aClosed - bClosed;

  const aTime = a.targetDate === null ? null : new Date(a.targetDate).getTime();
  const bTime = b.targetDate === null ? null : new Date(b.targetDate).getTime();
  if (aTime === null && bTime !== null) return 1;
  if (aTime !== null && bTime === null) return -1;
  if (aTime !== null && bTime !== null && aTime !== bTime) return aTime - bTime;

  if (a.createdAt === b.createdAt) return 0;
  return a.createdAt < b.createdAt ? -1 : 1;
}

async function withProgress(
  orgId: OrgId,
  projectId: ProjectId,
  rows: readonly Milestone[],
  now: Date,
): Promise<readonly MilestoneWithProgress[]> {
  const progress = await milestoneRepo.progressForProject(orgId, projectId);
  return [...rows].sort(compareMilestones).map((milestone) => {
    const counts = progress.get(milestone.id) ?? EMPTY_PROGRESS;
    return {
      milestone,
      progress: counts,
      overdue: isOverdue(milestone, counts, now),
    };
  });
}

async function loadWritableProject(actor: Actor, orgId: OrgId, projectId: ProjectId) {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const taken = await milestoneRepo.findMilestoneByNameKey(
    orgId,
    projectId,
    milestoneNameKey(name),
  );
  if (taken !== null && taken.id !== exceptId) {
    throw new MilestoneStateError("name_taken");
  }
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  await loadWritableProject(actor, input.orgId, input.projectId);

  const open = await milestoneRepo.countOpenMilestones(input.orgId, input.projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  await assertNameAvailable(input.orgId, input.projectId, input.name, null);

  const milestone = await milestoneRepo.insertMilestone(input);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await loadWritableProject(actor, input.orgId, current.projectId);

  if (input.name !== undefined) {
    await assertNameAvailable(
      input.orgId,
      current.projectId,
      input.name,
      current.id,
    );
  }

  if (input.name === undefined && input.targetDate === undefined) {
    return current;
  }

  return milestoneRepo.updateMilestone(input);
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await loadWritableProject(actor, input.orgId, current.projectId);

  if (current.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  let moveTo: MilestoneId | null = null;
  if (input.moveOpenIssuesTo !== null) {
    if (input.moveOpenIssuesTo === current.id) {
      throw new (await import("./_support")).NotFoundError(
        "Milestone",
        input.moveOpenIssuesTo,
      );
    }
    const target = requireFound(
      await milestoneRepo.findMilestoneById(input.orgId, input.moveOpenIssuesTo),
      "Milestone",
      input.moveOpenIssuesTo,
    );
    if (target.projectId !== current.projectId) {
      const { NotFoundError } = await import("./_support");
      throw new NotFoundError("Milestone", input.moveOpenIssuesTo);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
    moveTo = target.id;
  }

  const result = await milestoneRepo.closeMilestoneMovingIssues(
    input.orgId,
    current.id,
    moveTo,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: result.milestone.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds: result.movedIssueIds,
  });

  return result;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  await loadWritableProject(actor, orgId, current.projectId);

  if (current.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }

  const open = await milestoneRepo.countOpenMilestones(orgId, current.projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  const milestone = await milestoneRepo.setMilestoneClosedAt(orgId, milestoneId, null);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const rows = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  return withProgress(orgId, projectId, rows, new Date());
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const [row] = await withProgress(orgId, milestone.projectId, [milestone], new Date());
  return row!;
}

