      current.projectId,
      input.name,
      current.id,
    );
  }

  if (input.name === undefined && input.targetDate === undefined) {
    return current;
  }

  return milestoneRepo.updateMilestone(input);
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await loadWritableProject(actor, input.orgId, current.projectId);

  if (current.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  let moveTo: MilestoneId | null = null;
  if (input.moveOpenIssuesTo !== null) {
    if (input.moveOpenIssuesTo === current.id) {
      throw new (await import("./_support")).NotFoundError(
        "Milestone",
        input.moveOpenIssuesTo,
      );
    }
    const target = requireFound(
      await milestoneRepo.findMilestoneById(input.orgId, input.moveOpenIssuesTo),
      "Milestone",
      input.moveOpenIssuesTo,
    );
    if (target.projectId !== current.projectId) {
      const { NotFoundError } = await import("./_support");
      throw new NotFoundError("Milestone", input.moveOpenIssuesTo);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
    moveTo = target.id;
  }

  const result = await milestoneRepo.closeMilestoneMovingIssues(
    input.orgId,
    current.id,
    moveTo,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: result.milestone.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds: result.movedIssueIds,
  });

  return result;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  await loadWritableProject(actor, orgId, current.projectId);

  if (current.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }

  const open = await milestoneRepo.countOpenMilestones(orgId, current.projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  const milestone = await milestoneRepo.setMilestoneClosedAt(orgId, milestoneId, null);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const rows = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  return withProgress(orgId, projectId, rows, new Date());
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const [row] = await withProgress(orgId, milestone.projectId, [milestone], new Date());
  return row!;
}
