/**
 * A milestone an issue of `projectId` may join: it exists in the org, belongs
 * to that project, and is still open. Anything else is not found or closed.
 */
export async function requireOpenProjectMilestone(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  if (milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
  return milestone;
}

