{"type":"SearchReplace","EditsApplied":{"old_string":"export async function archiveIssue(","new_string":"/**
 * Puts an issue into an open milestone of its own project, moves it, or
 * clears the milestone. An archived issue cannot move.
 */
export async function setIssueMilestone(
  actor: Actor,
  input: SetIssueMilestoneInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  assertNotArchived("Project", project.id, project);

  if (input.milestoneId !== null) {
    await requireOpenProjectMilestone(
      input.orgId,
      issue.projectId,
      input.milestoneId,
    );
  }

  return issueRepo.setIssueMilestone(input.orgId, input.issueId, input.milestoneId);
}

